.venv/bin/python - <<'PY'
import duckdb
c = duckdb.connect()
c.execute("CREATE TABLE t AS SELECT * FROM (VALUES (1,'a'),(1,'a'),(1,'b')) v(x,y)")
try:
    print(c.execute("SELECT count(*) - count(DISTINCT t.x, t.y) AS duplicates FROM t").fetchall())
except Exception as e:
    print("ERR multi-arg distinct:", type(e).__name__, e)
try:
    print("range:", c.execute("WITH b AS (SELECT DATE '2020-01-01' a, DATE '2020-01-03' z) SELECT * FROM b CROSS JOIN range(b.a, b.z + INTERVAL 1 DAY, INTERVAL 1 DAY) AS d(day)").fetchall())
except Exception as e:
    print("ERR range:", type(e).__name__, e)
PY

